import { createHash, randomBytes } from "node:crypto";
import { PrismaClient } from "@prisma/client";

const db = new PrismaClient();
const stamp = Date.now();

function hashToken(t) {
  return createHash("sha256").update(t).digest("hex");
}

async function makeUser(tag, opts = {}) {
  const user = await db.user.create({
    data: {
      email: `dsar-${tag}-${stamp}@example.invalid`,
      name: `DSAR ${tag}`,
      passwordHash: "scrypt$deadbeef$deadbeef",
      stripeCustomerId: `cus_test_${tag}`,
      spendCapCredits: 500,
      ...opts,
    },
  });

  const token = randomBytes(32).toString("base64url");
  await db.session.create({
    data: {
      userId: user.id,
      tokenHash: hashToken(token),
      expiresAt: new Date(Date.now() + 30 * 86400000),
    },
  });

  const project = await db.project.create({
    data: {
      userId: user.id,
      name: `${tag} site`,
      slug: `dsar-${tag}-${stamp}`,
      publishedAt: new Date(),
    },
  });

  await db.projectFile.createMany({
    data: [
      { projectId: project.id, path: "index.html", content: `<h1>${tag} draft</h1>`, published: false, kind: "source" },
      { projectId: project.id, path: "index.html", content: `<h1>${tag} live</h1>`, published: true, kind: "build" },
      { projectId: project.id, path: "src/App.tsx", content: `export default function App(){return <p>${tag}</p>}`, published: false, kind: "source" },
    ],
  });

  await db.message.createMany({
    data: [
      { projectId: project.id, role: "user", content: `build me a ${tag} site` },
      { projectId: project.id, role: "assistant", content: `done, ${tag}` },
    ],
  });

  const build = await db.build.create({
    data: {
      projectId: project.id,
      status: "SUCCEEDED",
      model: "claude-test",
      prompt: `build me a ${tag} site`,
      endedAt: new Date(),
      inputTokens: 100,
      outputTokens: 200,
      filesWritten: 3,
      repairAttempts: 1,
      costMicros: 4000,
      creditsCharged: 2,
      filesSnapshot: { "index.html": `<h1>${tag} draft</h1>` },
    },
  });

  await db.creditLedger.create({
    data: { userId: user.id, delta: 750, reason: "signup", balanceAfter: 750 },
  });
  await db.creditLedger.create({
    data: { userId: user.id, delta: -2, reason: "build", buildId: build.id, balanceAfter: 748 },
  });
  await db.creditLedger.create({
    data: { userId: user.id, delta: 50, reason: `reward:discord:hash${tag}${stamp}`, balanceAfter: 798 },
  });
  await db.creditLedger.create({
    data: { userId: user.id, delta: 0, reason: `reward:instagram:pending:hashig${tag}${stamp}`, balanceAfter: 798 },
  });

  await db.event.createMany({
    data: [
      { userId: user.id, name: "user.signed_up", props: { method: "password" } },
      { userId: user.id, name: "project.published", props: { projectId: project.id } },
    ],
  });

  await db.supportNote.create({
    data: { userId: user.id, authorEmail: "ops@kodely.me", body: `${tag} asked about billing` },
  });

  await db.emailLog.create({
    data: { userId: user.id, kind: "welcome", dedupeKey: `${user.id}-welcome` },
  });

  await db.moderationFinding.create({
    data: {
      projectId: project.id,
      rule: "test.rule",
      severity: "low",
      path: "index.html",
      evidence: `${tag} evidence`,
      action: "recorded",
    },
  });

  return { user, token, projectId: project.id, buildId: build.id };
}

